 "content": "from collections import Counter, deque


def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    if not h or not w:
        return out

    counts = Counter(v for row in grid for v in row if v != 0)
    frame = counts.most_common(1)[0][0] if counts else 0

    # The colored centers are separate connected components; the most frequent
    # center color is the unmarked/default tile, while other colors are signals.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, frame) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            components.append((color, min(rs), max(rs), min(cs), max(cs)))

    center_counts = Counter(item[0] for item in components)
    if not center_counts:
        return out
    default = center_counts.most_common(1)[0][0]
    signals = set(center_counts) - {default}

    for color, r0, r1, c0, c1 in components:
        if color not in signals:
            continue
        for other, s0, s1, d0, d1 in components:
            if other != color:
                continue
            # Join horizontally aligned objects and vertically aligned objects.
            if (r0, r1) == (s0, s1) and c0 < d0:
                for y in range(r0, r1 + 1):
                    for x in range(c1 + 1, d0):
                        if grid[y][x] == 0:
                            out[y][x] = color
            if (c0, c1) == (d0, d1) and r0 < s0:
                for x in range(c0, c1 + 1):
                    for y in range(r1 + 1, s0):
                        if grid[y][x] == 0:
                            out[y][x] = color
    return out
